typedef long long ll;

// Fast modular exponentiation
ll mod_pow(ll base, ll exp, ll mod) {
    ll res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

// Multiply two numbers modulo mod (handles overflow)
ll mod_mul(ll a, ll b, ll mod) {
    ll res = 0;
    a %= mod;
    b %= mod;
    while (b > 0) {
        if (b & 1) res = (res + a) % mod;
        a = (a + a) % mod;
        b >>= 1;
    }
    return res;
}

