        ll L, A, B, M;
        scanf("%lld %lld %lld %lld", &L, &A, &B, &M);

        ll result = 0;
        ll term = A;

        for (ll i = 0; i < L; ) {
            // Determine number of digits in current term
            ll temp = term;
            int digits = 0;
            while (temp > 0) {
                digits++;
                temp /= 10;
            }
            if (term == 0) digits = 1;

            // Find the max term with same number of digits
            ll max_same_digits = 1;
            for (int d = 0; d < digits; d++) max_same_digits *= 10;
            max_same_digits--;  // e.g., 9, 99, 999...

            // How many terms we can take before digits increase
            ll step = B;
            if (step == 0) {
                // All terms same, process remaining all at once
                ll count = L - i;
                ll pow10 = mod_pow(10, digits, M);
                ll block_val = term % M;
                // geometric series for concatenation
                // result = result * 10^{digits*count} + block_val * (10^{digits*(count-1)} + ... + 1)
                ll pow_block = mod_pow(pow10, count, M);
                result = (mod_mul(result, pow_block, M) + 
                          mod_mul(block_val, (pow_block - 1 + M) % M * mod_pow(pow10 - 1 + M, M-2, M) % M, M)) % M;
                break;
            }

            ll max_term = term + step * (L - i - 1);
            ll limit = max_same_digits;
            if (max_term <= limit) {
                // all remaining have same digits
                ll count = L - i;
                ll pow10 = mod_pow(10, digits, M);
                ll block_val = term % M;
                ll pow_block = mod_pow(pow10, count, M);
                // Sum of geometric series: block_val * (pow_block - 1) / (pow10 - 1)
                ll inv = mod_pow((pow10 - 1 + M) % M, M-2, M);
                ll geom_sum = mod_mul(block_val, mod_mul((pow_block - 1 + M) % M, inv, M), M);
                result = (mod_mul(result, pow_block, M) + geom_sum) % M;
                break;
            }

            // Number of terms with current digit length
            ll count = (limit - term) / step + 1;
            if (count > L - i) count = L - i;

            ll pow10 = mod_pow(10, digits, M);
            ll block_val = term % M;
            ll pow_block = mod_pow(pow10, count, M);
            ll inv = mod_pow((pow10 - 1 + M) % M, M-2, M);
            ll geom_sum = mod_mul(block_val, mod_mul((pow_block - 1 + M) % M, inv, M), M);
            result = (mod_mul(result, pow_block, M) + geom_sum) % M;

            i += count;
            term += step * count;
        }

        printf("%lld\n", result);
    }
    return 0;
