typedef long long ll;
typedef __int128 i128;

typedef struct {
    ll a11, a12, a21, a22;
} Mat2;

static ll mod_mul(ll a, ll b, ll mod) {
    return (ll)((i128)a * b % mod);
}

static Mat2 mat_mul(Mat2 x, Mat2 y, ll mod) {
    Mat2 r;
    r.a11 = (mod_mul(x.a11, y.a11, mod) + mod_mul(x.a12, y.a21, mod)) % mod;
    r.a12 = (mod_mul(x.a11, y.a12, mod) + mod_mul(x.a12, y.a22, mod)) % mod;
    r.a21 = (mod_mul(x.a21, y.a11, mod) + mod_mul(x.a22, y.a21, mod)) % mod;
    r.a22 = (mod_mul(x.a21, y.a12, mod) + mod_mul(x.a22, y.a22, mod)) % mod;
    return r;
}

static Mat2 mat_pow(Mat2 base, ll exp, ll mod) {
    Mat2 r = {1 % mod, 0, 0, 1 % mod};
    while (exp > 0) {
        if (exp & 1) r = mat_mul(r, base, mod);
        base = mat_mul(base, base, mod);
        exp >>= 1;
    }
    return r;
}

static ll pow10_mod(int d, ll mod) {
    ll r = 1 % mod;
    ll a = 10 % mod;
    while (d > 0) {
        if (d & 1) r = mod_mul(r, a, mod);
        a = mod_mul(a, a, mod);
        d >>= 1;
    }
    return r;
}

static int digits_ll(ll x) {
    int d = 1;
    while (x >= 10) {
        x /= 10;
        d++;
    }
    return d;
}

/*
For a block where all terms have same digit length d:
x_{k+1} = p * x_k + (A' + B*k)   (mod M), where p = 10^d mod M
Let state vector be [x_k, k, 1]^T.
Transition:
[x_{k+1}]   [ p  B A'] [x_k]
[k+1    ] = [ 0  1  1 ] [k  ]
[1      ]   [ 0  0  1 ] [1  ]
Need x_n from x_0 = current_ans.
*/
typedef struct {
    ll m[3][3];
} Mat3;

static Mat3 mat3_mul(Mat3 a, Mat3 b, ll mod) {
    Mat3 r;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            i128 sum = 0;
            for (int k = 0; k < 3; k++) {
                sum += (i128)a.m[i][k] * b.m[k][j];
            }
            r.m[i][j] = (ll)(sum % mod);
        }
    }
    return r;
}

static Mat3 mat3_pow(Mat3 base, ll exp, ll mod) {
    Mat3 r = {{{1 % mod, 0, 0}, {0, 1 % mod, 0}, {0, 0, 1 % mod}}};
    while (exp > 0) {
        if (exp & 1) r = mat3_mul(r, base, mod);
        base = mat3_mul(base, base, mod);
        exp >>= 1;
    }
    return r;
}

static ll apply_block(ll cur, ll startA, ll B, ll cnt, int d, ll mod) {
    if (cnt == 0) return cur % mod;
    ll p = pow10_mod(d, mod);
    Mat3 T = {{
        {p % mod, B % mod, startA % mod},
        {0,       1 % mod, 1 % mod},
        {0,       0,       1 % mod}
    }};
    Mat3 P = mat3_pow(T, cnt, mod);

    ll v0 = cur % mod;
    ll v1 = 0;
    ll v2 = 1 % mod;

    i128 res = 0;
    res += (i128)P.m[0][0] * v0;
    res += (i128)P.m[0][1] * v1;
    res += (i128)P.m[0][2] * v2;
    return (ll)(res % mod);
}

int main(void) {
    int Q;
    if (scanf("%d", &Q) != 1) return 0;

    while (Q--) {
        ll L, A, B, M;
        scanf("%lld %lld %lld %lld", &L, &A, &B, &M);

        if (M == 1) {
            printf("0\n");
            continue;
        }

        ll ans = 0;
        ll used = 0;

        for (int d = 1; d <= 18 && used < L; d++) {
            ll low = 1;
            for (int i = 1; i < d; i++) low *= 10;
            ll high = low * 10 - 1;

            ll left = 0, right = L - 1, first = L;
            while (left <= right) {
                ll mid = left + (right - left) / 2;
                i128 val = (i128)A + (i128)B * mid;
                if (val >= low) {
                    first = mid;
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }

            left = 0; right = L - 1;
            ll last = -1;
            while (left <= right) {
                ll mid = left + (right - left) / 2;
                i128 val = (i128)A + (i128)B * mid;
                if (val <= high) {
                    last = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            if (first <= last && first < L && last >= 0) {
                if (first < 0) first = 0;
                if (last >= L) last = L - 1;
                ll cnt = last - first + 1;
                ll startA = (ll)((((i128)A + (i128)B * first) % M + M) % M);
                ans = apply_block(ans, startA, B % M, cnt, d, M);
                used += cnt;
            }
        }

        printf("%lld\n", ans % M);
    }

    return 0;
}

