public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            String[] parts = br.readLine().trim().split(" ");
            long L = Long.parseLong(parts[0]);
            long A = Long.parseLong(parts[1]);
            long B = Long.parseLong(parts[2]);
            long M = Long.parseLong(parts[3]);
            sb.append(solve(L, A, B, M)).append("\n");
        }
        System.out.print(sb);
    }

    static long solve(long L, long A, long B, long M) {
        long res = 0;
        long cur = A;
        long len = 1;
        long pow10 = 10;

        while (L > 0) {
            // Find the last term with the same digit length
            long maxVal = pow10 - 1;
            long lastSameLen;
            if (B == 0) {
                lastSameLen = cur;
            } else {
                lastSameLen = cur + B * (L - 1);
            }
            long limit = Math.min(maxVal, lastSameLen);
            long count;
            if (B == 0) {
                if (cur > maxVal) {
                    count = 0;
                } else {
                    count = L;
                }
            } else {
                if (cur > maxVal) {
                    count = 0;
                } else {
                    long maxSteps = (limit - cur) / B;
                    count = Math.min(L, maxSteps + 1);
                }
            }
            if (count <= 0) {
                // Move to next digit length
                len++;
                pow10 *= 10;
                continue;
            }

            // Use matrix exponentiation for this block
            // State: (res, cur, 1)
            // Transform for each term:
            // res' = (res * 10^len + cur) % M
            // cur' = (cur + B) % M
            // 1 stays 1
            long mod = M;
            long[][] trans = {
                {pow10 % mod, 1, 0},
                {0, 1, B % mod},
                {0, 0, 1}
            };
            long[][] init = {
                {res % mod},
                {cur % mod},
                {1}
            };
            long[][] matPow = matrixPow(trans, count, mod);
            long[][] finalState = matrixMul(matPow, init, mod);
            res = finalState[0][0] % mod;
            cur = (cur + B * count) % mod;
            L -= count;
            len++;
            pow10 *= 10;
        }
        return res % M;
    }

    static long[][] matrixMul(long[][] a, long[][] b, long mod) {
        int n = a.length;
        int m = b[0].length;
        int p = b.length;
        long[][] res = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                long sum = 0;
                for (int k = 0; k < p; k++) {
                    sum = (sum + a[i][k] * b[k][j]) % mod;
                }
                res[i][j] = sum;
            }
        }
        return res;
    }

    static long[][] matrixPow(long[][] base, long exp, long mod) {
        int n = base.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = matrixMul(res, base, mod);
            }
            base = matrixMul(base, base, mod);
            exp >>= 1;
        }
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // -------- Fast Scanner --------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    // -------- 2x2 Matrix for affine transform --------
    // Represents:
    // [x']   [a b] [x]
    // [1 ] = [0 1] [1]
    static class Mat {
        long a, b, mod; // second row is always [0,1]

        Mat(long a, long b, long mod) {
            this.a = a % mod;
            this.b = b % mod;
            this.mod = mod;
        }

        static Mat multiply(Mat x, Mat y) {
            long mod = x.mod;
            long na = mulMod(x.a, y.a, mod);
            long nb = (mulMod(x.a, y.b, mod) + x.b) % mod;
            return new Mat(na, nb, mod);
        }

        static Mat pow(Mat base, long exp) {
            long mod = base.mod;
            Mat res = new Mat(1, 0, mod);
            while (exp > 0) {
                if ((exp & 1L) != 0) res = multiply(res, base);
                base = multiply(base, base);
                exp >>= 1;
            }
            return res;
        }
    }

    static long mulMod(long a, long b, long mod) {
        // Safe for this problem using BigInteger-free repeated doubling
        long res = 0;
        a %= mod;
        b %= mod;
        while (b > 0) {
            if ((b & 1L) != 0) {
                res += a;
                if (res >= mod) res %= mod;
            }
            a += a;
            if (a >= mod) a %= mod;
            b >>= 1;
        }
        return res % mod;
    }

    static int digits(long x) {
        if (x >= 1000000000L) return 10;
        if (x >= 100000000L) return 9;
        if (x >= 10000000L) return 8;
        if (x >= 1000000L) return 7;
        if (x >= 100000L) return 6;
        if (x >= 10000L) return 5;
        if (x >= 1000L) return 4;
        if (x >= 100L) return 3;
        if (x >= 10L) return 2;
        return 1;
    }

    static long solveOne(long L, long A, long B, long M) {
        if (M == 1) return 0;

        long ans = 0;
        long[] pow10 = new long[19];
        pow10[0] = 1;
        for (int i = 1; i < pow10.length; i++) pow10[i] = pow10[i - 1] * 10L;

        for (int d = 1; d <= 18; d++) {
            long low = pow10[d - 1];
            long high = (d == 18 ? Long.MAX_VALUE : pow10[d] - 1);

            // Find i range where low <= A + B*i <= high, and 0 <= i <= L-1
            long left = 0, right = L - 1;

            if (B == 0) {
                if (A < low || A > high) continue;
                long cnt = L;
                long p = modPow10(d, M);

                // Repeatedly: ans = ans * p + A
                Mat trans = new Mat(p, A % M, M);
                Mat total = Mat.pow(trans, cnt);
                ans = (mulMod(total.a, ans, M) + total.b) % M;
                continue;
            }

            long li = ceilDiv(low - A, B);
            long ri = floorDiv(high - A, B);

            if (li < left) li = left;
            if (ri > right) ri = right;
            if (li > ri) continue;

            long cnt = ri - li + 1;
            long first = A + B * li;
            long p = modPow10(d, M);

            // State vector [ans, currentTerm, 1]
            // ans' = p*ans + currentTerm
            // term' = term + B
            //
            // But we can eliminate currentTerm using affine composition on pair (ans, term).
            // 3x3 would work, but simpler to process block by binary exponentiation on transform:
            // f(ans, t) = (p*ans + t, t + B)
            // We'll use 3x3 matrix.
            long[][] base = {
                    {p % M, 1 % M, 0},
                    {0, 1 % M, B % M},
                    {0, 0, 1 % M}
            };
            long[][] mat = matPow(base, cnt, M);

            long newAns = (
                    mulMod(mat[0][0], ans, M) +
                    mulMod(mat[0][1], first % M, M) +
                    mat[0][2]
            ) % M;
            ans = newAns;
        }

        return ans % M;
    }

    static long modPow10(int d, long mod) {
        long res = 1 % mod;
        long base = 10 % mod;
        int e = d;
        while (e > 0) {
            if ((e & 1) != 0) res = mulMod(res, base, mod);
            base = mulMod(base, base, mod);
            e >>= 1;
        }
        return res;
    }

    static long ceilDiv(long a, long b) {
        // b > 0
        if (a >= 0) return (a + b - 1) / b;
        return a / b;
    }

    static long floorDiv(long a, long b) {
        // b > 0
        if (a >= 0) return a / b;
        return -((-a + b - 1) / b);
    }

    static long[][] matMul(long[][] A, long[][] B, long mod) {
        int n = A.length;
        int m = B[0].length;
        int k = B.length;
        long[][] C = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int t = 0; t < k; t++) {
                if (A[i][t] == 0) continue;
                for (int j = 0; j < m; j++) {
                    if (B[t][j] == 0) continue;
                    C[i][j] = (C[i][j] + mulMod(A[i][t], B[t][j], mod)) % mod;
                }
            }
        }
        return C;
    }

    static long[][] matPow(long[][] base, long exp, long mod) {
        int n = base.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1 % mod;
        while (exp > 0) {
            if ((exp & 1L) != 0) res = matMul(base, res, mod);
            base = matMul(base, base, mod);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int Q = fs.nextInt();
        for (int qi = 0; qi < Q; qi++) {
            long L = fs.nextLong();
            long A = fs.nextLong();
            long B = fs.nextLong();
            long M = fs.nextLong();
            out.append(solveOne(L, A, B, M)).append('\n');
        }
        System.out.print(out.toString());
    }
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

// multiply two numbers modulo mod, avoiding overflow for 64-bit
int64 mulmod(int64 a, int64 b, int64 mod) {
    int64 res = 0;
    a %= mod;
    while (b > 0) {
        if (b & 1) res = (res + a) % mod;
        a = (a * 2) % mod;
        b >>= 1;
    }
    return res;
}

// fast exponentiation modulo mod
int64 powmod(int64 base, int64 exp, int64 mod) {
    int64 res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = mulmod(res, base, mod);
        base = mulmod(base, base, mod);
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;
    while (Q--) {
        int64 L, A, B, M;
        cin >> L >> A >> B >> M;

        int64 result = 0;
        int64 current = A;
        int64 len = 1; // current digit length
        int64 power10 = 10; // 10^len

        while (L > 0) {
            // find last term in current digit-length block
            int64 max_val = power10 - 1;
            int64 last = current + B * (L - 1);

            int64 cnt;
            if (current > max_val) {
                // move to next digit length
                len++;
                power10 *= 10;
                continue;
            }
            if (last <= max_val) {
                cnt = L;
            } else {
                cnt = (max_val - current) / B + 1;
            }

            // first term of block: current
            // last term of block: current + B*(cnt-1)
            // geometric series for concatenation:
            // sum_{i=0}^{cnt-1} (current + i*B) * (10^{len})^{(cnt-1-i)}

            int64 step = cnt;
            int64 mod = M;

            // precompute pow10_len = 10^len mod M
            int64 pow10_len = powmod(10, len, M);

            // compute sum of geometric series for concatenation:
            // S = current * (pow10_len^{cnt} - 1) / (pow10_len - 1) * (1 / pow10_len?) 
            // Better: iterative block merge approach using binary exponentiation

            // We'll compute using fast doubling for concatenation:
            // function f(len_block, first, diff, count)
            // returns (concatenated_value_mod, power_of_10_mod)

            // Use iterative doubling
            int64 pow10_block = powmod(pow10_len, cnt, M);

            // Compute sum = first * (pow10_len^{cnt-1}) + (first+B) * (pow10_len^{cnt-2}) + ...
            // Let's use formula for arithmetic-geometric series:
            // Let r = pow10_len
            // S = first * (r^{cnt} - 1)/(r-1) + B * (r^{cnt-1} + 2*r^{cnt-2} + ... + (cnt-1)*r^0)
            // We'll compute iteratively with fast doubling to avoid division issues.

            // simpler: use fast doubling merge:
            // (val, p10) for concatenation of block
            auto merge = [&](int64 val1, int64 p101, int64 val2, int64 p102) -> pair<int64,int64> {
                return { (mulmod(val1, p102, M) + val2) % M, mulmod(p101, p102, M) };
            };

            function<pair<int64,int64>(int64,int64,int64,int64)> block_concat;
            block_concat = [&](int64 first_val, int64 diff, int64 count, int64 r) -> pair<int64,int64> {
                if (count == 0) return {0, 1};
                if (count == 1) return {first_val % M, r % M};
                if (count % 2 == 0) {
                    auto left = block_concat(first_val, diff, count/2, r);
                    // right block starts at first_val + diff*(count/2)
                    auto right = block_concat((first_val + diff*(count/2)) % M, diff, count/2, r);
                    return merge(left.first, left.second, right.first, right.second);
                } else {
                    auto left = block_concat(first_val, diff, count-1, r);
                    auto last_term = (first_val + diff*(count-1)) % M;
                    return merge(left.first, left.second, last_term, r);
                }
            };

            auto [block_val, _] = block_concat(current % M, B % M, cnt, pow10_len);

            // merge with current result
            result = (mulmod(result, powmod(10, len*cnt, M), M) + block_val) % M;

            L -= cnt;
            current += B * cnt;
            len++;
            power10 *= 10;
        }

        cout << result % M << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

ll mod;

ll mulmod(ll a, ll b) { return (lll)a * b % mod; }
ll addmod(ll a, ll b) { return (a + b) % mod; }

ll power(ll base, ll exp, ll m) {
    ll result = 1; base %= m;
    while(exp > 0) { if(exp&1) result = (lll)result*base%m; base=(lll)base*base%m; exp>>=1; }
    return result;
}

// returns {sum_{i=0}^{n-1} p^i, sum_{i=0}^{n-1} i*p^i} mod
pair<ll,ll> geosum(ll n, ll p) {
    if(n == 0) return {0, 0};
    if(n == 1) return {1, 0};
    ll half = n/2;
    auto [s1, s2] = geosum(half, p);
    ll ph = power(p, half, mod);
    ll ns1 = addmod(s1, mulmod(ph, s1));
    ll ns2 = addmod(s2, mulmod(ph, addmod(s2, mulmod(half % mod, s1))));
    if(n % 2 == 1) {
        ns1 = addmod(ns1, power(p, n-1, mod));
        ns2 = addmod(ns2, mulmod((n-1) % mod, power(p, n-1, mod)));
    }
    return {ns1, ns2};
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Mat {
    long long a00, a01, a10, a11;
};

static inline long long mul_mod(long long a, long long b, long long mod) {
    return (long long)((i128)a * b % mod);
}

static inline long long add_mod(long long a, long long b, long long mod) {
    a += b;
    if (a >= mod) a -= mod;
    return a;
}

static inline Mat mul_mat(const Mat& A, const Mat& B, long long mod) {
    Mat C;
    C.a00 = (mul_mod(A.a00, B.a00, mod) + mul_mod(A.a01, B.a10, mod)) % mod;
    C.a01 = (mul_mod(A.a00, B.a01, mod) + mul_mod(A.a01, B.a11, mod)) % mod;
    C.a10 = (mul_mod(A.a10, B.a00, mod) + mul_mod(A.a11, B.a10, mod)) % mod;
    C.a11 = (mul_mod(A.a10, B.a01, mod) + mul_mod(A.a11, B.a11, mod)) % mod;
    return C;
}

static inline Mat pow_mat(Mat base, long long exp, long long mod) {
    Mat res{1 % mod, 0, 0, 1 % mod};
    while (exp > 0) {
        if (exp & 1) res = mul_mat(res, base, mod);
        base = mul_mat(base, base, mod);
        exp >>= 1;
    }
    return res;
}

// Apply T^cnt to state [ans, cur]^T where:
// ans' = p * ans + cur
// cur' = cur + B
// T = [[p,1],[0,1]] composed with cur increment handled by affine lifting:
// state [ans, cur, 1], but we can derive a 2x2 on [ans, cur] when B=0 only.
// So instead we use formula:
// ans after cnt steps = p^cnt * ans + cur * sum p^k + B * sum_{t=0}^{cnt-1} sum_{k=0}^{cnt-1-t} p^k
// Easier: use 3x3 matrix.
struct Mat3 {
    long long a[3][3];
};

static inline Mat3 mul_mat3(const Mat3& A, const Mat3& B, long long mod) {
    Mat3 C{};
    for (int i = 0; i < 3; ++i) {
        for (int k = 0; k < 3; ++k) if (A.a[i][k]) {
            for (int j = 0; j < 3; ++j) {
                C.a[i][j] = (C.a[i][j] + (i128)A.a[i][k] * B.a[k][j]) % mod;
            }
        }
    }
    return C;
}

static inline Mat3 pow_mat3(Mat3 base, long long exp, long long mod) {
    Mat3 res{};
    for (int i = 0; i < 3; ++i) res.a[i][i] = 1 % mod;
    while (exp > 0) {
        if (exp & 1) res = mul_mat3(res, base, mod);
        base = mul_mat3(base, base, mod);
        exp >>= 1;
    }
    return res;
}

static inline long long count_len(long long L, long long A, long long B, long long low, long long high) {
    // count i in [0, L-1] such that low <= A + B*i <= high
    if (L <= 0) return 0;
    if (B == 0) {
        return (low <= A && A <= high) ? L : 0;
    }
    // Since B >= 0 in intended setting for arithmetic progression lengths by digits.
    // Binary-search style integer bounds.
    long long left = 0, right = L; // first i with A+B*i >= low
    while (left < right) {
        long long mid = (left + right) >> 1;
        i128 val = (i128)A + (i128)B * mid;
        if (val >= low) right = mid;
        else left = mid + 1;
    }
    long long l = left;

    left = 0; right = L; // first i with A+B*i > high
    while (left < right) {
        long long mid = (left + right) >> 1;
        i128 val = (i128)A + (i128)B * mid;
        if (val > high) right = mid;
        else left = mid + 1;
    }
    long long r = left;

    if (l >= r) return 0;
    return r - l;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;
    while (Q--) {
        long long L, A, B, M;
        cin >> L >> A >> B >> M;

        if (M == 1) {
            cout << 0 << '\n';
            continue;
        }

        long long ans = 0;
        long long cur = A;
        long long done = 0;

        for (int d = 1; d <= 18 && done < L; ++d) {
            long long low = (d == 1 ? 0LL : (long long)pow(10LL, d - 1));
            long long high = (d == 18 ? LLONG_MAX : (long long)pow(10LL, d) - 1);

            long long cnt = count_len(L, A, B, low, high);

            // Need only the next cnt terms in order; because digit ranges are contiguous for nondecreasing AP.
            // Skip empty groups.
            if (cnt == 0) continue;

            long long p = 1 % M;
            for (int i = 0; i < d; ++i) p = mul_mod(p, 10, M);

            // State vector [ans, cur, 1]^T
            // one step:
            // ans' = p*ans + cur
            // cur' = cur + B
            // 1' = 1
            Mat3 T{};
            T.a[0][0] = p;
            T.a[0][1] = 1 % M;
            T.a[0][2] = 0;
            T.a[1][0] = 0;
            T.a[1][1] = 1 % M;
            T.a[1][2] = B % M;
            T.a[2][0] = 0;
            T.a[2][1] = 0;
            T.a[2][2] = 1 % M;

            Mat3 P = pow_mat3(T, cnt, M);

            long long nans = ((i128)P.a[0][0] * ans + (i128)P.a[0][1] * (cur % M) + P.a[0][2]) % M;
            long long ncur = ((i128)P.a[1][0] * ans + (i128)P.a[1][1] * (cur % M) + P.a[1][2]) % M;

            ans = nans;
            cur = (A + (i128)B * (done + cnt)) % M; // keep exact progression position modulo M
            done += cnt;
        }

        cout << ans % M << '\n';
    }

    return 0;
}
